commits.content:
{
	"schemaVersion": 1,
	"id": "customstacklimit",
	"version": "${version}",
	"name": "CustomStackLimit",
	"description": "アイテムのスタック数を64個以上にカスタマイズできるMod。/stack コマンドで設定可能。",
	"authors": [
		"chihalu"
	],
	"contact": {
		"homepage": "https://fabricmc.net/",
		"sources": "https://github.com/FabricMC/fabric-example-mod"
	},
	"license": "CC0-1.0",
	"icon": "assets/customstacklimit/icon.png",
	"environment": "*",
	"entrypoints": {
		"main": [
			"chihalu.customstacklimit.CustomStackLimit"
		],
		"client": [
			"chihalu.customstacklimit.CustomStackLimitClient"
		],
		"fabric-datagen": [
			"chihalu.customstacklimit.CustomStackLimitDataGenerator"
		]
	},
	"mixins": [
		"customstacklimit.mixins.json",
		{
			"config": "customstacklimit.client.mixins.json",
			"environment": "client"
		}
	],
	"depends": {
		"fabricloader": ">=0.17.3",
		"minecraft": "~1.21.9",
		"java": ">=21",
		"fabric-api": "*"
	},
	"suggests": {
		"another-mod": "*"
	}
}
